function StatusPanel({game}:{game:Game}) { return <aside className="status-panel"><div className="status-title"><span>업무 상태</span><b>LV {Math.max(1,Math.floor(game.score/200)+1)}</b></div><div className="status-row"><span>인사고과</span><b>{game.grade}</b><i><em style={{width:`${game.grade}%`}}/></i></div><div className="status-row"><span>친밀도</span><b>{game.trust}</b><i><em style={{width:`${game.trust}%`}}/></i></div><div className="status-currency"><span>업무 코인</span><b>{game.coins}</b></div></aside> }
function RelationshipPanel({game}:{game:Game}) { return <aside className="relationship-panel glass"><div className="relationship-heading"><span>관계도</span><small>대화 상대별 독립 수치</small></div><div className="relationship-list">{roster.map(p=><div className="relationship-row" key={p.key}><span><b>{p.name}</b><small>{p.role}</small></span><strong>{game[p.key]??0}</strong><i><em style={{width:`${Math.min(100,game[p.key]??0)}%`}}/></i></div>)}</div></aside> }
export default function App(){
 const [view,setView]=useState<'home'|'play'|'result'|'ending'|'catalog'|'board'>('home'),[name,setName]=useState(''),[game,setGame]=useState<Game|null>(null),[sceneIndex,setSceneIndex]=useState(0),[questionIndex,setQuestionIndex]=useState<0|1>(0),[quizOrders,setQuizOrders]=useState<Record<string,string[]>>({}),[choice,setChoice]=useState<number|null>(null),[checked,setChecked]=useState(false),[previewOnly,setPreviewOnly]=useState(false),[board,setBoard]=useState<Game[]>([]),[history,setHistory]=useState<Game[]>([]),[error,setError]=useState(''),[storyStep,setStoryStep]=useState<0|1|2>(0),[logOpen,setLogOpen]=useState(false),[relationsOpen,setRelationsOpen]=useState(false),[reviewOpen,setReviewOpen]=useState(false),[autoPlay,setAutoPlay]=useState(false),[skipPlay,setSkipPlay]=useState(false),[endingChoice,setEndingChoice]=useState<keyof typeof endingChoiceCopy | null>(null),[endingReviewOpen,setEndingReviewOpen]=useState(false),[endingCatalog,setEndingCatalog]=useState<string[]>([]),[endingSummariesSaved,setEndingSummariesSaved]=useState<Record<string,string[]>>({}),[catalogDetail,setCatalogDetail]=useState<keyof typeof ENDING_RULES | null>(null),[soundOpen,setSoundOpen]=useState(false),[soundSettings,setSoundSettings]=useState(()=>soundscape.settings()),[floating,setFloating]=useState<{text:string; kind:'good'|'bad'}|null>(null)
 const flags=read<Flags>(game?.flags,{projectHealth:50,deadlineRisk:50,reputation:50}); const learned=read<string[]>(game?.learned,[])
 const reviewItems=useMemo<ReviewItem[]>(()=>learned.map((id): ReviewItem | null =>{const located=scenes.find(s=>[s.fixedQuiz,...s.poolQuiz].some(item=>item.id===id));const item=located&&[located.fixedQuiz,...located.poolQuiz].find(value=>value.id===id);return item&&located?{id:item.id,kind:'learned',day:located.day,scene:located.title,line:item.line,pattern:item.pattern,meaning:item.meaning,example:item.example,options:item.options}:null}).filter((item):item is ReviewItem=>Boolean(item)).reverse(),[learned])
 const wrongNotes=useMemo<ReviewItem[]>(()=>{try{return JSON.parse(localStorage.getItem('office-review-wrong-notes')??'[]')}catch{return[]}},[game?.answers])
 const activeDay:1|2|3=game?.day===3?3:game?.day===2?2:1; const dayScenes=scenes.filter(s=>s.day===activeDay); const scene=dayScenes[sceneIndex]; const poolId=quizOrders[scene?.id]?.[0]; const rawQuiz=scene && (questionIndex===0?scene.fixedQuiz:scene.poolQuiz.find(x=>x.id===poolId)??scene.poolQuiz[0]); const quiz=rawQuiz&&{...rawQuiz,options:quizOrders[`${rawQuiz.id}:options`] ? quizOrders[`${rawQuiz.id}:options`].map(id=>rawQuiz.options.find(o=>o.text===id)!).filter(Boolean) : rawQuiz.options}; const selected=choice===null?undefined:quiz?.options[choice]; const correct=Boolean(selected?.correct)
 const arrange=(index=0)=>{const order:Record<string,string[]>={}; scenes.forEach(s=>{order[s.id]=shuffle(s.poolQuiz).map(x=>x.id); [...s.poolQuiz,s.fixedQuiz].forEach(item=>order[`${item.id}:options`]=shuffle(item.options).map(o=>o.text))});setQuizOrders(order);setSceneIndex(index);setQuestionIndex(0);setChoice(null);setChecked(false);setStoryStep(0);setError('')}
 const beginAudio=()=>soundscape.activate()
 const syncSound=()=>setSoundSettings({...soundscape.settings()})
 useEffect(()=>{if(view!=='play'){setAutoPlay(false);setSkipPlay(false)}},[view])
 useEffect(()=>{if(view==='play'){soundscape.setMood(sceneIndex%8>=6?'night':sceneIndex%8===5?'warm':'bright')}},[view,sceneIndex])
 useEffect(()=>{if(view==='ending')soundscape.play('ending')},[view])
 const loadHistory=async()=>{try{const r=await api('games');if(r.ok)setHistory(await r.json())}catch{setHistory([])}}; useEffect(()=>{loadHistory();try{setEndingCatalog(JSON.parse(localStorage.getItem(ENDING_CATALOG_KEY)??'[]'));setEndingSummariesSaved(JSON.parse(localStorage.getItem(ENDING_SUMMARY_KEY)??'{}'))}catch{setEndingCatalog([]);setEndingSummariesSaved({})}},[])
 const start=async()=>{beginAudio();if(!name.trim()){setError('이름을 입력한 뒤 출근을 시작해 주세요.');return}try{const r=await api('games',json({player:name.trim()}));if(!r.ok)throw Error();setGame(await r.json());setPreviewOnly(false);arrange();setView('play')}catch{setError('새 근무 기록을 시작하지 못했어요. 잠시 후 다시 시도해 주세요.')}}
 const preview=()=>{beginAudio();setGame(blankGame);setPreviewOnly(true);arrange();setView('play')}
 const advance=()=>{if(!checked){soundscape.play('dialogue');setStoryStep(s=>s===0?1:2)}}
 const submit=async(index:number)=>{if(!game||checked||storyStep!==2||!quiz||!scene)return;const option=quiz.options[index],isRight=option.correct,points=isRight?100:0,rel=isRight?8:-3,trust=isRight?4:-7,coins=isRight?15:2;soundscape.play('select');window.setTimeout(()=>{soundscape.play(isRight?'correct':'wrong');soundscape.play(isRight?'affinity':'scene');if(isRight)soundscape.play('coin')},70);setFloating({text:isRight?'♥ +8':'💦 -8',kind:isRight?'good':'bad'});window.setTimeout(()=>setFloating(null),900);const nextFlags={projectHealth:Math.max(0,Math.min(100,flags.projectHealth+(isRight?5:-4))),deadlineRisk:Math.max(0,Math.min(100,flags.deadlineRisk+(isRight?-4:7))),reputation:Math.max(0,Math.min(100,flags.reputation+(isRight?5:-5)))};const nextLearned=Array.from(new Set([...learned,quiz.id]));const answer:Answer={scene_index:sceneIndex,choice_index:index,question_index:questionIndex,quiz_id:quiz.id,correct:Number(isRight),points};const nextGame:Game={...game,score:game.score+points,grade:Math.max(0,game.grade+(isRight?0:-8)),trust:Math.max(0,Math.min(100,game.trust+trust)),coins:game.coins+coins,[scene.relationKey]:Math.max(0,Math.min(100,(game[scene.relationKey]??0)+rel)),current_scene:sceneIndex,day:sceneIndex===dayScenes.length-1&&questionIndex===1&&activeDay===1?2:activeDay,flags:nextFlags,learned:nextLearned,answers:[...(game.answers??[]),answer]};if(!isRight){try{const note:ReviewItem={id:quiz.id,kind:'wrong',day:activeDay,scene:scene.title,line:quiz.line,pattern:quiz.pattern,meaning:quiz.meaning,example:quiz.example,options:quiz.options,chosen:option.text,whyWrong:option.whyWrong};const saved=JSON.parse(localStorage.getItem('office-review-wrong-notes')??'[]') as ReviewItem[];localStorage.setItem('office-review-wrong-notes',JSON.stringify([note,...saved.filter(item=>item.id!==note.id)].slice(0,40)))}catch{}}setChoice(index);setChecked(true);setGame(nextGame);if(previewOnly)return;try{const r=await api(`games/${game.id}/answers`,json({scene_index:sceneIndex,choice_index:index,question_index:questionIndex,quiz_id:quiz.id,correct:isRight,points,grade_delta:isRight?0:-8,affinity_delta:rel,trust_delta:trust,coins_delta:coins,relationship_key:scene.relationKey,relationship_delta:rel,current_scene:sceneIndex,day:sceneIndex===dayScenes.length-1&&questionIndex===1&&activeDay===1?2:activeDay,flags:nextFlags,learned:nextLearned,completed:sceneIndex===dayScenes.length-1&&questionIndex===1&&activeDay===3}));if(!r.ok)throw Error();const saved=await r.json();setGame({...saved,answers:nextGame.answers});loadHistory()}catch{setError('화면에는 반영됐지만 기록 저장에 실패했어요.')}}
 const next=()=>{soundscape.play('scene');if(questionIndex===0){setQuestionIndex(1);setChoice(null);setChecked(false);setStoryStep(0);return}if(sceneIndex===dayScenes.length-1){if(activeDay===3){setEndingChoice(null);setView('ending')}else setView('result');return}setSceneIndex(v=>v+1);setQuestionIndex(0);setChoice(null);setChecked(false);setStoryStep(0)}
 useEffect(()=>{if(!skipPlay||view!=='play'||checked||storyStep===2)return;const timer=window.setTimeout(advance,150);return()=>window.clearTimeout(timer)},[skipPlay,view,checked,storyStep,sceneIndex,questionIndex])
 useEffect(()=>{if(!autoPlay||view!=='play'||!checked)return;const timer=window.setTimeout(next,2500);return()=>window.clearTimeout(timer)},[autoPlay,view,checked,sceneIndex,questionIndex])
 useEffect(()=>{const onKeyDown=(event:KeyboardEvent)=>{const target=event.target as HTMLElement|null;if(target?.matches('input, textarea, select, [contenteditable="true"]'))return;const key=event.key.toLowerCase();if(event.key==='Escape'){setLogOpen(false);setRelationsOpen(false);setReviewOpen(false);setSoundOpen(false);return}if(key==='a'){setAutoPlay(value=>!value);setSkipPlay(false);return}if(key==='s'){setSkipPlay(value=>!value);setAutoPlay(false);return}if(key==='l'){setLogOpen(value=>!value);return}if(view!=='play'||logOpen||relationsOpen||reviewOpen||soundOpen)return;if(['1','2','3','4'].includes(event.key)&&storyStep===2&&!checked){event.preventDefault();submit(Number(event.key)-1);return}if(event.key===' '||event.key==='Enter'){event.preventDefault();checked?next():advance()}};window.addEventListener('keydown',onKeyDown);return()=>window.removeEventListener('keydown',onKeyDown)},[view,logOpen,relationsOpen,reviewOpen,soundOpen,storyStep,checked,sceneIndex,questionIndex,quiz,game])
 const dialogueLog=(game?.answers??[]).map(a=>{const s=scenes.find(scene=>[scene.fixedQuiz,...scene.poolQuiz].some(item=>item.id===a.quiz_id))??dayScenes[a.scene_index];const item=[s.fixedQuiz,...s.poolQuiz].find(x=>x.id===a.quiz_id)??s.fixedQuiz;return{a,s,item}})
 const rows=useMemo(()=>dayScenes.map((s,i)=>({title:s.title,points:(game?.answers??[]).filter(a=>a.scene_index===i).reduce((n,a)=>n+a.points,0)})), [game,activeDay])
 const homeStats=useMemo(()=>{const uniqueLearned=new Set<string>();history.forEach(record=>read<string[]>(record.learned,[]).forEach(id=>uniqueLearned.add(id)));return {plays:history.length,best:history.reduce((best,record)=>Math.max(best,record.score??0),0),learned:uniqueLearned.size,endings:endingCatalog.length}},[history,endingCatalog]); const sortedHistory=useMemo(()=>[...history].sort((a,b)=>String(b.updated_at??'').localeCompare(String(a.updated_at??''))),[history]); const displaySetting=scene?.id==='d2s1'?(flags.projectHealth>=55?'어제 공유한 초안 덕분에 킥오프가 매끄럽게 시작됐다. 대표가 프로젝트 개요와 일정을 설명한 뒤 진행 상황 공유를 요청한다.':flags.projectHealth<=45?'마감 직전 수정으로 팀이 조금 지쳐 있다. 대표가 프로젝트 개요와 일정을 설명한 뒤 더 자주 진행 상황을 공유해 달라고 요청한다.':scene.setting):scene?.setting??''; const endingGrade=game?(Object.keys(ENDING_RULES) as Array<keyof typeof ENDING_RULES>).find(key=>ENDING_RULES[key].check(game,flags))??'C':null; const unlockEnding=(grade:string)=>{try{const saved=Array.from(new Set([...endingCatalog,grade]));localStorage.setItem(ENDING_CATALOG_KEY,JSON.stringify(saved));setEndingCatalog(saved)}catch{}}; const chooseEnding=(choice:keyof typeof endingChoiceCopy)=>{setEndingChoice(choice);const grade=endingGrade??'C';unlockEnding(grade);try{const next={...endingSummariesSaved,[grade]:endingSummaries[grade]};localStorage.setItem(ENDING_SUMMARY_KEY,JSON.stringify(next));setEndingSummariesSaved(next)}catch{}}; const beginDay2=async()=>{if(!game)return;const nextGame={...game,day:2 as const,current_scene:0,completed:0};setGame(nextGame);arrange(0);setView('play');if(!previewOnly){try{const response=await api(`games/${game.id}/advance-day`,json({day:2}));if(!response.ok)throw Error();setGame(await response.json());loadHistory()}catch{setError('둘째 날 전환 기록 저장에 실패했어요.')}}}; const beginDay3=async()=>{if(!game)return;const nextGame={...game,day:3 as const,current_scene:0,completed:0};setGame(nextGame);arrange(0);setView('play');if(!previewOnly){try{const response=await api(`games/${game.id}/advance-day`,json({day:3}));if(!response.ok)throw Error();setGame(await response.json());loadHistory()}catch{setError('셋째 날 전환 기록 저장에 실패했어요.')}}}; const openBoard=async()=>{setView('board');try{const r=await api('leaderboard');if(r.ok)setBoard(await r.json())}catch{setError('점수판을 불러오지 못했어요.')}}
 return <div className="app-shell"><header className="topbar"><button className="brand" onClick={()=>setView('home')}>OFFICE ENGLISH</button></header>
 {view==='home'&&<main className="home page game-home"><section className="hero"><div><p className="kicker">3 DAY OFFICE STORY · DAY 1 OPEN</p><h1>오늘의 업무,<br/><span>영어로 성장!</span></h1><p className="intro">하루에 8개 업무 장면, 장면마다 핵심 퀴즈와 랜덤 실무 퀴즈를 풀며 프로젝트 킥오프를 준비하세요.</p><div className="start-row"><label className="name-field"><span>플레이어 이름</span><input value={name} onChange={e=>setName(e.target.value.slice(0,24))} placeholder="이름을 입력해 주세요"/></label><button className="primary-btn" onClick={start}>DAY 1 시작 <span>→</span></button></div><button className="secondary-btn preview-entry" onClick={preview}>게임 화면 바로 보기 ↗</button><button className="secondary-btn preview-entry" onClick={()=>setReviewOpen(true)}>📖 표현 복습장</button><button className="secondary-btn preview-entry" onClick={()=>setView('catalog')}>엔딩 도감</button>{error&&<p className="error-msg">{error}</p>}</div><div className="home-character"><Character person="소피 · 팀장님"/></div></section><section className="home-records glass" aria-label="나의 기록"><p className="kicker">MY OFFICE RECORD</p><h2>나의 기록</h2><div className="record-summary"><div><span>총 플레이</span><b>{homeStats.plays}</b><small>회</small></div><div><span>최고 점수</span><b>{homeStats.best}</b><small>pt</small></div><div><span>모은 표현</span><b>{homeStats.learned}</b><small>개</small></div><div><span>엔딩 수집</span><b>{homeStats.endings}</b><small>/ 4</small></div></div></section><section className="resume"><p className="kicker">SAVED RECORDS</p><h2>이어하기</h2>{sortedHistory.length>0?<div className="history-list">{sortedHistory.map(g=><button className="history-row" key={g.id} onClick={()=>{setGame(g);setPreviewOnly(false);arrange(Math.min(g.current_scene??0,(g.day===3?scenes.filter(s=>s.day===3):g.day===2?scenes.filter(s=>s.day===2):scenes.filter(s=>s.day===1)).length-1));setView(g.completed?'result':'play')}}><strong>{g.player}</strong><span>DAY {g.day??1} · {g.score}점 · 인사고과 {g.grade}</span><b>이어하기 →</b></button>)}</div>:<p className="resume-empty">저장된 근무 기록이 아직 없어요. DAY 1을 시작하면 여기에서 이어서 진행할 수 있어요.</p>}</section></main>}
 {view==='play'&&game&&scene&&quiz&&<main className="play-page visual-novel-page"><section className={`vn-stage scene-${sceneIndex + (activeDay-1)*8}`}><header className="mini-hud glass"><span className="hud-time">DAY {activeDay} / 3 · {scene.time}</span><span>SCENE {sceneIndex+1}/{dayScenes.length}</span><span>★ {game.score}</span><span>인사 {game.grade}</span><span>◈ {game.coins}</span><button onClick={()=>{beginAudio();soundscape.setEnabled(!soundSettings.enabled);syncSound()}} aria-label="소리 켜기 또는 끄기">{soundSettings.enabled?'🔊':'🔇'}</button><button onClick={()=>{beginAudio();setSoundOpen(v=>!v)}} aria-label="사운드 설정">⚙️</button>{soundOpen&&<div className="sound-panel glass"><label>배경음 <input type="range" min="0" max="100" value={soundSettings.bgmLevel} onChange={e=>{soundscape.setBgmLevel(Number(e.target.value));syncSound()}}/><b>{soundSettings.bgmLevel}</b></label><label>효과음 <input type="range" min="0" max="100" value={soundSettings.sfxLevel} onChange={e=>{soundscape.setSfxLevel(Number(e.target.value));syncSound()}}/><b>{soundSettings.sfxLevel}</b></label></div>}<button onClick={()=>setRelationsOpen(true)}>관계도</button><button className={`pace-toggle ${autoPlay?'is-active':''}`} onClick={()=>{setAutoPlay(value=>!value);setSkipPlay(false)}} aria-pressed={autoPlay}>AUTO</button><button className={`pace-toggle ${skipPlay?'is-active':''}`} onClick={()=>{setSkipPlay(value=>!value);setAutoPlay(false)}} aria-pressed={skipPlay}>SKIP</button><button onClick={()=>setReviewOpen(true)}>📖 복습장</button><button className="log-button" onClick={()=>setLogOpen(true)}>LOG</button></header><div className="stage-backdrop"><i/><i/><i/></div><Character key={scene.id} person={scene.person} mood={checked?(correct?'happy':'worried'):'neutral'}/>{floating&&<div className={`floating-score ${floating.kind}`}>{floating.text}</div>}{storyStep===2&&!checked&&<div className="choice-overlay"><section className="choice-popup glass" aria-label="답변 선택"><p className="kicker">CHOOSE YOUR RESPONSE</p><h2>{quiz.prompt}</h2><div className="options">{quiz.options.map((option,index)=><button type="button" className="option" key={option.text} onMouseEnter={()=>soundscape.play('hover')} onClick={()=>submit(index)}><span className="option-letter">{String.fromCharCode(65+index)}</span><span>{option.text}</span></button>)}</div></section></div>}{checked&&<aside className={`manager-feedback vn-feedback ${correct?'good':'bad'}`}><span className="speaker">{scene.person} · COACHING</span><strong>{correct?'좋아요. 실무에서도 바로 쓰기 좋은 선택이에요.':'잠깐! 이 표현은 지금 상황에선 아쉬워요.'}</strong><p>{correct?`“${selected?.text}” — 정확하고 자연스럽습니다.`:`“${selected?.text}” — ${selected?.whyWrong} 회사가 놀이터냐는 말 듣기 전에 표현을 다듬어 볼까요?`}</p><b>추천 표현 · “{quiz.options.find(o=>o.correct)?.text}”</b><div className="reward-line floating-reward">{correct?'+100 점 · ♥ +8 · 친밀도 +4 · 코인 +15':'인사고과 -8 · 호감도 -3 · 친밀도 -7 · 코인 +2'}</div><div className="expression-note"><span>실무 표현 노트</span><p><b>Pattern</b> {quiz.pattern}</p><p><b>Meaning</b> {quiz.meaning}</p><p><b>Example</b> {quiz.example}</p></div><button className="vn-next primary-btn" onClick={next}>{questionIndex===0?'랜덤 퀴즈로':'다음 시간대로'} <span>→</span></button></aside>}<div className="dialogue-wrap"><span className="question-chip">Q {questionIndex+1}/2 · {questionIndex===0?'고정':'랜덤'}</span><TypeDialogue speaker={storyStep===0?'SITUATION':storyStep===1?scene.person:quiz.speaker} text={storyStep===0?displaySetting:storyStep===1?`“${scene.line}”`:`“${quiz.line}”`} onAdvance={advance} autoAdvanceDelay={autoPlay?1800:null}/></div></section>{relationsOpen&&<div className="log-overlay relation-overlay"><section className="log-panel relationship-dialog"><div className="log-heading"><h2>인물별 호감도</h2><button className="secondary-btn" onClick={()=>setRelationsOpen(false)}>닫기</button></div><RelationshipPanel game={game}/></section></div>}{logOpen&&<div className="log-overlay"><section className="log-panel"><div className="log-heading"><h2>이전 대화</h2><button className="secondary-btn" onClick={()=>setLogOpen(false)}>닫기</button></div>{dialogueLog.length===0?<p className="log-empty">아직 기록된 대화가 없어요.</p>:<div className="log-list">{dialogueLog.map(({a,s,item})=><article key={`${a.quiz_id}-${a.choice_index}`}><span>{s.time} · Q {a.question_index+1}/2</span><p><b>{item.speaker}</b> “{item.line}”</p><em>{a.correct?'정답 · +100점':'오답 · 인사고과 -8'}</em></article>)}</div>}</section></div>}</main>}
 {view==='result'&&game&&<main className="page result-page"><header className="result-heading"><p className="kicker">DAY {activeDay} COMPLETE</p><h1>DAY {activeDay} · <span>{activeDay===1?'첫날 기록':activeDay===2?'둘째 날 기록':'셋째 날 기록'}</span></h1></header><div className="result-stats result-summary"><div><span>점수</span><b>{game.score}</b><small>pt</small></div><div><span>인사고과</span><b>{game.grade}</b><small>점</small></div><div><span>코인</span><b>{game.coins}</b><small>개</small></div></div><p className="result-learning-line">이번 날 배운 표현 <b>{learned.length}개</b> · 정답률 <b>{game.answers?.length?Math.round((game.answers.filter(answer=>answer.correct).length/game.answers.length)*100):0}%</b></p><div className="chapter-teaser glass"><b>{activeDay===1?'다음 날: 프로젝트 킥오프와 첫 위기':'다음 날: 최종 발표와 마감'}</b><span>{activeDay===1?'오늘 배운 표현과 팀의 신뢰가 내일의 첫 회의를 바꿉니다.':'오늘의 선택이 내일 최종 발표의 자신감이 됩니다.'}</span></div><section className="scene-score-list"><h2>시간대별 기록</h2>{rows.map((r,i)=><div className="scene-score-row" key={r.title}><span>{String(i+1).padStart(2,'0')}</span><strong>{r.title}</strong><b>{r.points} pt</b></div>)}</section><div className="result-actions"><button className="primary-btn" onClick={activeDay===1?beginDay2:beginDay3}>{activeDay===1?'DAY 2 시작':'DAY 3 시작'} <span>→</span></button><button className="secondary-btn" onClick={openBoard}>점수판</button></div></main>}
 {view==='ending'&&game&&<main className="page result-page ending-page">{!endingChoice?<><p className="kicker">DAY 3 COMPLETE · 마지막 날 엔딩</p><h1>{game.player}님의<br/><span>오늘의 마무리</span></h1><div className="chapter-teaser glass"><b>마지막 선택</b><span>3일간의 프로젝트를 어떤 마음으로 마무리할까요?</span></div><div className="result-actions"><button className="primary-btn" onClick={()=>chooseEnding('dinner')}>소피와 저녁</button><button className="secondary-btn" onClick={()=>chooseEnding('home')}>귀가하기</button><button className="secondary-btn" onClick={()=>chooseEnding('team')}>회식 잔류</button></div></>:<><div className="ending-particles" aria-hidden="true">{Array.from({length:14},(_,index)=><i key={index}/>)}</div><div className={`ending-grade grade-${endingGrade??'C'}`}>{endingGrade??'C'}</div><p className="kicker">YOUR ENDING</p><h1>{game.player}님의<br/><span>{ENDING_RULES[endingGrade??'C'].title}</span></h1><section className="ending-story-cards"><article className="glass"><small>PROJECT</small><b>프로젝트 결과</b><p>프로젝트는 {flags.projectHealth>=55?'안정적인 흐름으로':'끝까지 집중하며'} 마무리되었습니다.</p></article><article className="glass"><small>TEAM</small><b>팀 관계</b><p>{endingChoiceCopy[endingChoice]}</p></article><article className="glass"><small>GROWTH</small><b>나의 성장</b><p>3일 동안 쌓은 실무 표현과 책임 있는 대응이 다음 도전의 힘이 되었습니다.</p></article></section><section className="ending-total glass"><h2>3일 누적 기록</h2><div><span>누적 점수</span><b>{game.score} pt</b></div><div><span>인사고과</span><b>{game.grade}점</b></div><div><span>배운 표현</span><b>{learned.length}개</b></div></section><RelationshipPanel game={game}/><section className="scene-score-list expression-review"><button className="expression-toggle" onClick={()=>setEndingReviewOpen(value=>!value)} aria-expanded={endingReviewOpen}><span>배운 표현 복습 <small>{learned.length}개</small></span><b>{endingReviewOpen?'접기 ↑':'펼치기 ↓'}</b></button>{endingReviewOpen&&<div className="review-list">{learned.slice(0,40).map(id=>{const item=scenes.flatMap(s=>[s.fixedQuiz,...s.poolQuiz]).find(q=>q.id===id);return item?<article key={id}><b>{item.pattern}</b><span>{item.meaning}</span><em>{item.example}</em></article>:null})}{learned.length===0&&<p>아직 저장된 표현이 없어요.</p>}</div>}</section><div className="result-actions ending-actions"><button className="primary-btn" onClick={()=>{setGame(null);setEndingReviewOpen(false);setView('home')}}>다시 하기</button><button className="secondary-btn" onClick={()=>setView('catalog')}>엔딩 도감</button><button className="secondary-btn" onClick={openBoard}>점수판</button></div></>}</main>}
 {view==='catalog'&&<main className="page result-page catalog-page"><p className="kicker">ENDING COLLECTION</p><h1>엔딩 도감</h1><p className="catalog-intro">완주한 결말을 눌러 그날의 마지막 기록을 다시 읽어 보세요.</p><section className="ending-grid" aria-label="엔딩 목록">{(Object.keys(ENDING_RULES) as Array<keyof typeof ENDING_RULES>).map(grade=>{const unlocked=endingCatalog.includes(grade);return <button key={grade} className={`ending-card ${unlocked?'unlocked':'locked'}`} disabled={!unlocked} onClick={()=>setCatalogDetail(grade)}><span className="ending-badge">{unlocked?grade:'🔒'}</span><small>{unlocked?'ENDING UNLOCKED':'LOCKED ENDING'}</small><strong>{unlocked?ENDING_RULES[grade].title:'???'}</strong><em>{unlocked?'기록 보기 →':'아직 만나지 못한 결말'}</em></button>})}</section>{catalogDetail&&<div className="catalog-overlay" role="dialog" aria-modal="true" aria-label="엔딩 요약"><section className="catalog-modal glass"><button className="review-close" onClick={()=>setCatalogDetail(null)} aria-label="엔딩 요약 닫기">×</button><span className="ending-badge">{catalogDetail}</span><p className="kicker">ENDING MEMORY</p><h2>{ENDING_RULES[catalogDetail].title}</h2>{(endingSummariesSaved[catalogDetail]??endingSummaries[catalogDetail]).map(line=><p key={line}>{line}</p>)}</section></div>}<div className="result-actions"><button className="primary-btn" onClick={()=>setView('home')}>홈으로 돌아가기</button></div></main>}
 {view==='board'&&<main className="page board-page"><div className="board-heading"><div><p className="kicker">OFFICE LEADERBOARD</p><h1>오늘의 에이스</h1></div><button className="secondary-btn" onClick={()=>setView('home')}>← 하루 시작</button></div><div className="board-table"><div className="board-row board-header"><span>순위</span><span>플레이어</span><span>친밀도</span><span>팀장 호감</span><span>점수</span></div>{board.length===0?<div className="board-empty">아직 기록이 없어요.</div>:board.map((r:any)=><div className="board-row" key={`${r.player}-${r.rank}`}><span>{String(r.rank).padStart(2,'0')}</span><strong>{r.player}</strong><span>{r.trust??50}</span><span>{r.sophie_affinity??0}</span><b>{r.score} pt</b></div>)}</div></main>}<ReviewModal open={reviewOpen} onClose={()=>setReviewOpen(false)} learned={reviewItems} wrongNotes={wrongNotes}/></div>
}
